function toggleMenu(){document.getElementById("nav-menu").classList.toggle("active"),document.querySelector(".overlay").classList.toggle("active")}function calcularAgua(){const e=window.converterParaNumero(document.getElementById("peso").value),t=window.converterParaNumero(document.getElementById("atividade").value),o=parseInt(document.getElementById("clima").value),n=document.getElementById("resultado-area"),a=document.getElementById("copos-visual");if(isNaN(e)||e<=0)return void alert("Por favor, informe seu peso corretamente.");let l=35*e,c=l+l*(t-1)+o,r=c/1e3;const d=Math.round(c/300);n.style.display="block",document.getElementById("valor-agua").textContent=r.toFixed(2)+" Litros",document.getElementById("valor-ml").textContent=Math.round(c),document.getElementById("qtd-copos").textContent=d,a.innerHTML="";const i=Math.min(d,15);for(let e=0;e<i;e++){const e=document.createElement("span");e.textContent="🥤",e.className="cup-icon active",a.appendChild(e)}if(d>15){const e=document.createElement("span");e.textContent="+",e.style.alignSelf="center",e.style.fontWeight="bold",e.style.color="var(--cor-primaria)",a.appendChild(e)}window.innerWidth<600&&n.scrollIntoView({behavior:"smooth",block:"start"}),"function"==typeof window.salvarCalculo&&window.salvarCalculo("Calculadora de Água",`Peso: ${e}kg | Nível: ${t} | Clima: ${o>0?"Quente":"Frio"}`,`Meta: ${r.toFixed(2)}L (${d} copos)`)}